<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Role extends MY_Controller {
    public function __construct(){parent::__construct();$this->require_login();$this->require_permission('role.manage');$this->load->model('Role_model');}
    public function index():void{$roles=$this->Role_model->all();$map=array();foreach($roles as &$role){$role['users_count']=$this->Role_model->users_count((int)$role['id']);$map[$role['id']]=$this->Role_model->permission_codes((int)$role['id']);}unset($role);$this->load->view('layout/main',array('title'=>'Role & Permission','view'=>'role/index','data'=>array('rows'=>$roles,'permissions'=>$this->Role_model->permissions(),'role_permissions'=>$map)));}
    public function save():void{$id=(int)$this->input->post('id');$old=$id?$this->Role_model->find($id):NULL;if($old&&$old['kode']==='SUPERADMIN')$this->respond(FALSE,'SUPERADMIN tidak dapat diubah.',array(),array(),403);$data=array('kode'=>strtoupper(trim((string)$this->input->post('kode',TRUE))),'nama'=>$this->input->post('nama',TRUE),'keterangan'=>$this->input->post('keterangan',TRUE),'aktif'=>(int)$this->input->post('aktif',TRUE));if(!$data['kode']||!$data['nama'])$this->respond(FALSE,'Kode dan nama role wajib diisi.',array(),array(),422);if($old&&$old['kode']!==$data['kode']&&$old['is_system'])$this->respond(FALSE,'Kode role bawaan tidak boleh diubah.',array(),array(),403);$this->respond(TRUE,'Role tersimpan',array('id'=>$this->Role_model->save($data,$id)));}
    public function matrix(int $id):void{$role=$this->Role_model->find($id);if(!$role)$this->respond(FALSE,'Role tidak ditemukan.',array(),array(),404);if($this->input->method(TRUE)==='GET'){$this->respond(TRUE,'OK',array('permissions'=>$this->Role_model->permission_codes($id)));}if($role['kode']==='SUPERADMIN')$this->respond(FALSE,'Permission SUPERADMIN terkunci.',array(),array(),403);$this->Role_model->sync_permissions($id,(array)$this->input->post('permission_ids'));$this->respond(TRUE,'Permission role diperbarui.');}
    public function delete(int $id):void{$role=$this->Role_model->find($id);if(!$role)$this->respond(FALSE,'Role tidak ditemukan.',array(),array(),404);if($role['is_system']||$role['kode']==='SUPERADMIN'||$this->Role_model->users_count($id)>0)$this->respond(FALSE,'Role bawaan atau masih digunakan tidak dapat dihapus.',array(),array(),422);$this->db->where('id',$id)->delete('roles');$this->respond(TRUE,'Role dihapus.');}
}
